CREATE TABLE public.service_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_key uuid NOT NULL UNIQUE, name text NOT NULL, email text NOT NULL, phone text, service_id text NOT NULL, details text NOT NULL, appointment_start timestamptz, calendar_event_id text, meet_url text, notification_status text NOT NULL DEFAULT 'pending', payment_status text NOT NULL DEFAULT 'quote_required', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.service_requests TO authenticated; GRANT ALL ON public.service_requests TO service_role; ALTER TABLE public.service_requests ENABLE ROW LEVEL SECURITY; CREATE POLICY "Admins read service requests" ON public.service_requests FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'::public.app_role)); CREATE TRIGGER service_requests_updated BEFORE UPDATE ON public.service_requests FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();